<?php defined( 'ABSPATH' ) || exit; $system = $result['data']['system'] ?? $result['data'] ?? []; ?>
<article class="cyberfort-ai-register cyberfort-ai-register__system">
<?php if ( ! empty( $result['error'] ) || ! is_array( $system ) || empty( $system ) ) : ?><p class="cyberfort-ai-register__error"><?php esc_html_e( 'The public AI systems register is temporarily unavailable. Please try again later.', 'cyberfort-ai-register' ); ?></p><?php else : ?><h1><?php echo esc_html( $system['name'] ?? $reference ); ?></h1><dl><?php foreach ( [ 'reference' => __( 'Reference', 'cyberfort-ai-register' ), 'status' => __( 'Status', 'cyberfort-ai-register' ), 'risk_tier' => __( 'Risk tier', 'cyberfort-ai-register' ), 'purpose' => __( 'Purpose', 'cyberfort-ai-register' ), 'intended_users' => __( 'Intended users', 'cyberfort-ai-register' ), 'human_oversight' => __( 'Human oversight', 'cyberfort-ai-register' ) ] as $field => $label ) : if ( isset( $system[ $field ] ) && '' !== $system[ $field ] ) : ?><dt><?php echo esc_html( $label ); ?></dt><dd><?php echo esc_html( is_scalar( $system[ $field ] ) ? (string) $system[ $field ] : wp_json_encode( $system[ $field ] ) ); ?></dd><?php endif; endforeach; ?></dl><?php endif; ?>
</article>
